#!/usr/bin/env python3
"""Source-driven portfolio expansion; editorial heuristics, never match statistics."""
import json,pathlib,collections,re,math,datetime
R=pathlib.Path(__file__).resolve().parents[1]
from data_io import read_data,save_analysis
read=lambda p:read_data(R,p)
def save(p,v):
 if p=='data/deck-analysis.json':save_analysis(R,v)
 else:(R/p).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
C={x['id']:x for x in read('data/cards.json')}; H={x['id']:x for x in read('data/heroes.json')}
D=[d for d in read('data/decks.json') if d['category'] not in ['source-portfolio','theme-theorycraft']]; A={k:v for k,v in read('data/deck-analysis.json').items() if k in {d['id'] for d in D}}; P=read('data/card-analysis.json'); COR=read('research/meta-corpus.json')
# A profile requires a real payoff. Secondary packages remain visible instead of
# labelling every list containing one generic removal spell a control deck.
E={}
def engine(key,title,core,plan,sequence,weak,style='tempo',power=7,rng=2):
 E[key]=dict(title=title,core=core.split('|'),plan=plan,sequence=sequence,weak=weak,style=style,power=power,rng=rng)
engine('force_patch','Force Patch','Soul_Patch|Force_Field','Купить время защитой героя и завершить игру оставшимися угрозами; защитный пакет не заменяет способ победить.','Force Field стоит 4, Soul Patch — 6: совместная установка без скидок стоит 10. Поле ставится только на ground. Заранее выставленная среда экономит солнце позднее, но выдаёт линию и позволяет Zombies заменить её после Plants. Перенаправленный урон не повреждает Patch в поле; уничтожение и bounce не являются уроном.','Дешёвая замена среды плюс hard removal разбирают инвестицию; ранняя агрессия не даёт потратить 4 солнца на пустое поле.','control',6,2)
engine('bmr','Bad Moon Rising','Bad_Moon_Rising','Сохранить несколько недорогих тел, затем обменять качество каждого на случайное существо за 5+; важнее число живых оснований, чем дорогая исходная атака.','BMR стоит 7 и разыгрывается в Zombie Tricks. На обычном седьмом ходу без дополнительных трат хватает ресурса, но тела должны пережить Plants Play. Brain Vendor за 3 возвращает 3: сам по себе не создаёт прибыль. В заранее установленной Medulla (+2) он даёт чистые +2 за текущий ход при свободной линии. Один Vendor на четвёртом ходу оставляет 4−3+3+2=6, поэтому обещать BMR за 7 на этом ходу без ещё одного источника нельзя. Результат 5+, а не гарантированный Zombot; полезность When played зависит от результата и фазы.','Удаление оснований, Brainana и налог на трюки лишают одновременно ресурса и будущих превращений.','combo',6,9)
engine('beans','Bean pressure','Admiral_Navy_Bean|Jelly_Bean|Bean_Counter','Использовать Beans как полезные тела и триггеры, а не набивать руку случайными существами без темпа.','Jelly Bean получает bounce от Bean Evolution: нужен Bean на поле, который будет заменён. Admiral наносит прямой урон при розыгрыше Beans; погибший Admiral больше не создаёт триггеров. Подмешанные Lima-карты не равны немедленному добору.','Массовый урон по мелким телам и раннее убийство Admiral обрывают накопление урона.','tempo',7,2)
engine('freeze_p','Freeze execution','Winter_Squash|Snowdrop|Snow_Pea|Iceberg_Lettuce','Замедлять угрозы Freeze, растить Snowdrop и при доступном Squash превращать остановку в удаление.','Snowdrop растёт от заморозки зомби, а Winter Squash уничтожает замороженного зомби/надгробие. Сначала выставьте payoff, затем Freeze; заморозка до появления Squash не даёт задним числом уничтожения.','Teleport после потраченной заморозки и удаление payoff обходят план; пустые freeze-карты дают плохую руку.','control',6,2)
engine('amphibious','Water and crossfire','Marine_Bean|Laser_Cattail|Rotobaga|Navy_Bean','Разделить давление между водой и соседними линиями, заставляя противника отвечать несколькими типами карт.','Amphibious открывает воду, но среду туда положить нельзя. Rotobaga атакует соседние линии: выбор места меняет цель, наличие самого Rotobaga в линии не означает удар по этой линии.','Splash и точечное удаление ключевых водных угроз гасят преимущество свободной линии.','tempo',7,2)
engine('starfruit','Starfruit crossfire','Shooting_Starfruit|Threepeater|Tricorn','Получать несколько ударов из одной угрозы и выигрывать за счёт линий, которые трудно закрыть одновременно.','Считайте каждую линию отдельно, её блокера и порядок боя. Бафф одной многолинейной угрозы может увеличить несколько атак, но цена подготовки делает её уязвимой до боя.','Одно качественное удаление крупной многолинейной угрозы обменивается на весь пакет усилений.','combo',6,3)
engine('pea','Pea evolution','Gatling_Pea|Podfather|Pea_Patch','Давить пригодными для атаки Peas, сохраняя одно основание для взрывного Evolution вместо бессмысленного заполнения всех линий.','Gatling требует Pea Evolution для бонусной атаки. Bonk Choy не Pea; пригодность основания проверяется по типу карточки. Дополнительный удар может уйти в блокера или блок героя.','Removal до эволюции и bounce дорогого финишера отнимают основание и темп.','aggro',8,2)
engine('rings','Onion hand conversion','Onion_Rings','Обменять один ход подготовки на несколько дешёвых 4/4 из руки; сохранять дешёвые тела в руке до превращения.','Onion Rings меняет растения в текущей руке на 4/4 при розыгрыше; уже стоящие растения и последующий добор не получают изменение задним числом.','Быстрый burn наказывает ход без немедленного давления, а возврат/удаление не даёт дорогому плану окупиться.','midrange',7,2)
engine('apotk','Untrickable OTK','Apotatosaurus|Espresso_Fiesta','Сохранить крупную Untrickable-угрозу и завершить игру дополнительными атаками, а не надеяться на медленный естественный бой.','Apotatosaurus стоит 6, Fiesta 7: без скидок это 13 ресурсов за совместную установку, поэтому нужны разные ходы или ramp. Untrickable мешает трюкам, но не способностям существ, среды или блокерам.','Primordial Cheese Shover и другие способности существ обходят Untrickable; агрессия сокращает время подготовки.','combo',7,2)
engine('moss','Repeat Moss engine','Repeat_Moss','Связать сохранённый Moss с серией полезных трюков, каждый из которых запускает дополнительную атаку.','Moss должен уже находиться на поле, когда играется трюк. Сначала посчитайте расходы на установку и трюки, затем блокеры и блок; сила героя доступна только если она действительно в руке.','Удаление Moss до серии и блок в неверный момент ломают расчёт летала.','combo',8,2)
engine('banana','Banana scaling','Half-Banana|Bananasaurus_Rex|Banana_Split','Получать выгоду от семейства Banana и растущих угроз, не уступая раннюю кривую только ради красивого взаимодействия.','Уточните условие Half-Banana по карточной записи и момент его выполнения. Bananasaurus растёт от получения карт через Dino-Roar; атаки и блок разрешаются отдельно.','Один hard removal снимает вложения в растущую угрозу; широкий swarm требует отвечать раньше.','midrange',7,3)
engine('potted','Growth reserve','Potted_Powerhouse|Doubled_Mint','Накапливать усиления и угрозу в руке, вынуждая противника тратить ответы до появления позднего payoff.','Potted должен быть в руке в момент нужного события роста. Не считайте усиления, случившиеся до его получения; большое число характеристик само по себе не даёт обхода блокера.','Bounce и hard removal игнорируют накопленные характеристики.','combo',6,2)
engine('conjure_p','Plant discovery','Captain_Cucumber|Bird_of_Paradise|Reincarnation|Plucky_Clover','Использовать генерацию как дополнительный ресурс после обязательного развития, а не как обещание нужной легендарки.','Conjure добавляет случайную карту; Shuffle меняет колоду, Draw достаёт из колоды. Держите свободное место в руке и пересчитывайте план после каждого случайного результата.','Темповая агрессия наказывает слабые generating-тела, налог делает случайные дорогие карты ещё медленнее.','value',5,8)
engine('anti_trick','Taxed tempo','Forget-Me-Nuts|Black_Eyed_Pea|Sportacus','Давить телами, пока каждое удаление трюком становится дороже или подпитывает ваше поле.','Forget-Me-Nuts повышает цену трюков, Black-Eyed Pea растёт при Zombie Tricks. Налог исчезает после удаления носителя; игра существом вместо трюка может обойти наказание.','Большие существа и раскрытия надгробий не обязаны проходить через ваши штрафы на трюки.','tempo',8,2)
engine('three_nut','Three-Nut swarm','Three-Nut','Превратить дешёвые Team-Up/слабые тела в качественную атакующую массу и выиграть эффективностью нескольких карт за ход.','Сначала Three-Nut, затем подходящие новые тела: эффект применяется к дальнейшим розыгрышам. Не рассчитывайте, что он автоматически усиливает всю старую доску.','Массовая зачистка и удаление Three-Nut перед продолжением уменьшают отдачу.','aggro',7,2)
engine('pecan','Health attacks','Pecanolith','Собирать высокое здоровье как будущую атаку и использовать смену оси боя для неожиданного финиша.','Pecanolith меняет атакующее число у ОБЕИХ сторон. Перед установкой сравните здоровье в каждой линии: Teleportation Zombie 1/5 тоже начнёт бить на 5. Потеря здоровья уменьшает будущий урон.','Крупные здоровые зомби пользуются той же сменой оси; hard removal снимает ключевой payoff.','combo',6,3)
engine('mirror','Mirror-Nut attrition','Mirror-Nut','Выигрывать через реальные события повреждения Nuts, защищая отражатель и не отдавая всё поле в один массовый ответ.','Текущий Mirror-Nut — 0/11 Team-Up Bullseye; триггер даёт 1 урон, а не старые 2. Force Field предотвращает повреждения Nuts в своей линии и поэтому НЕ усиливает этот триггер.','Уничтожение вместо урона и bounce обходят цепочку триггеров.','control',6,2)
engine('roots','Root economy','Starch_Lord','Сочетать Root-темп и постепенную генерацию, не превращая каждый ход в ожидание случайной дорогой карты.','Starch-Lord баффает новые Roots и сам относится к Root. Проверьте тип каждого получателя; похожее название растения не доказывает принадлежность к Root.','Темповое удаление Starch-Lord и высокие цены случайных Roots тормозят окупаемость.','value',6,5)
engine('bowling','Bowling control','Wall-Nut_Bowling','Снять раннее давление, пережить середину и конвертировать поздний запас ресурса в прямой финишер.','Bowling стоит 8; считайте реальные свободные ground-линии и итоговые удары по карточному тексту. Его цена требует ранних ответов, а не руки из одних финишеров.','Быстрая агрессия и надёжный поздний burst заканчивают игру раньше дорогого трюка.','control',6,2)
engine('heal','Heal conversion','Pepper_M.D.|Heartichoke|Venus_Flytraplanet','Лечиться с выгодой для поля/урона, сохраняя хотя бы один источник угрозы; высокий запас здоровья не является победой.','Рост Pepper требует реального восстановления здоровья, а не попытки лечить полностью здоровую цель. Heartichoke и Flytraplanet могут связать лечение с уроном; цепочка зависит от недостающего здоровья и блока, не объявляйте её бесконечной.','Sneezing Zombie ограничивает лечение, высокий burst пробивает запас здоровья, Untrickable избегает части removal.','control',7,2)
engine('flowers','Flower retaliation','Briar_Rose|Power_Flower','Получать пользу от цветочного поля и наказания за повреждение, сохраняя давление наряду с защитой.','Тип Flower должен быть указан на карточке. Briar Rose не превращает bounce или уничтожение без повреждения в событие hurt.','Removal без урона и массовые ответы на маленькие Flowers снижают плотность триггеров.','midrange',6,2)
engine('ramp_p','Solar acceleration','Twin_Sunflower|Sunnier_Shroom|Sun_Shroom|Metal_Petal_Sunflower','Вложить ранний ресурс в будущие большие ходы, сохранив достаточно дешёвых ответов на потерю темпа.','Постоянное солнце важно лишь пока источники живы в требуемый момент. Рассчитайте базовое солнце плюс живой ramp и не учитывайте уничтоженный Sunflower.','Агрессия уничтожает ramp и выигрывает до первого крупного payoff; дорогая рука без источника ресурса уязвима.','ramp',6,2)
engine('strikethrough_p','Solar lane pressure','Elderberry|Astrocado|Bloomerang|Laser_Bean','Получать урон по герою через блокера и одновременно создавать угрозы, на которые нужен отдельный ответ.','Strikethrough проходит сквозь бойца, но не отменяет блок героя. Elderberry требует Plant Evolution для полного payoff — проверьте основание и цену его потери.','Быстрый burn сокращает гонку, bounce дорогой угрозы покупает ход, Armored уменьшает маленькие порции урона.','aggro',8,2)
engine('berries','Berry damage','Sergeant_Strongberry|Strawberrian|High-Voltage_Currant','Давить Berry-синергиями и точечным уроном, одновременно открывая линии для атак.','Проверяйте Berry-тип и конкретное событие на каждой карте: случайно похожее растение не активирует пакет. Сохраняйте двигатель до продолжения, а не ставьте все тела под одну зачистку.','Удаление двигателя и крупные здоровые существа перегружают несколько маленьких источников урона.','tempo',6,2)
engine('pineclone','Pineclone conversion','Pineclone','Создать много дешёвых тел, затем превратить число растений в одинаковые 3/3 до того, как каждое тело разменяют.','Pineclone преобразует ВСЕ ваши растения, включая полезные двигатели и себя; теряются исходные способности. Превращение не является уничтожением для death-триггеров.','Массовая зачистка и темповый remove до четвёртого хода уменьшают число результатов.','aggro',7,3)
engine('molekale','Plant transformation','Molekale|Imitater|Petal-Morphosis','Обменивать подготовленные дешёвые/многочисленные тела на новый набор случайных угроз, имея запасной темповый путь.','Molekale повышает стоимость каждого другого растения ровно на 1 через случайный результат. Два превращения не гарантируют конкретную легендарку; новое существо получает свои правила, а старый двигатель исчезает.','Removal оснований до преобразования и неудачный результат заставляют потерять темп.','combo',5,9)
engine('mushrooms','Mushroom swarm','Gloom-Shroom|Punish-Shroom|Mushroom_Ringleader|Buff_Shroom','Создавать плотное грибное поле и превращать дешёвые тела в групповой бонус/поздний финишер.','Gloom-Shroom требует Mushroom Evolution для полного эффекта. Подходящий Mushroom должен остаться на поле; Evolution меняет основание, а не даёт отдельную дополнительную линию.','Splash и массовый урон особенно выгодны против нескольких дешёвых тел.','aggro',7,2)
engine('cycle','Cyclecap draw loop','Astro_Shroom|Planet_of_the_Grapes','Ставить недорогие растения, получать Bullseye-урон от Astro и поддерживать руку добором среды.','Astro должен стоять в Planet для добора от его урона герою. Bullseye не заряжает блок. Сначала оплачивается среда, потом каждое новое тело; отсутствие свободных мест останавливает цепь.','Environment replacement и удаление Astro обрывают engine, а ранний burn выигрывает до подготовки.','combo',7,3)
engine('splash_p','Splash board control','Snapdragon|Shrinking_Violet|Melon-Pult|Kernel_Corn','Обменивать одну карту на несколько угроз и после очистки атаковать сохранившимися телами.','Splash и debuff оценивайте по реальным соседним линиям. Shrinking Violet не становится мгновенным уничтожением любой крупной угрозы; проверяйте итоговые характеристики.','Одиночные крупные угрозы, невидимые grave и burst по герою уменьшают ценность массового ответа.','control',7,2)
engine('imps','Imp network','Toxic_Waste_Imp|Imp_Commander|Imposter|Imp_Throwing_Imp','Превратить недорогие Imps в устойчивый источник разменов, добора и урона в нескольких линиях.','Toxic Waste даёт Deadly Imps, но это не делает их Untrickable. Imp Commander добирает при уроне Imp по герою; удар в растение и заблокированный удар не равны этому событию.','Mass removal и быстрое удаление Toxic/Commander делают маленькие тела обычными.','aggro',8,2)
engine('pirates','Pirate breakthrough','Captain_Flameface|Swashbuckler_Zombie|Space_Pirate','Создать раннее давление и дать Pirates проходить сквозь блокеров, сохраняя темп вместо ожидания одного дорогого финишера.','Проверяйте Pirate-тип. Текущий Captain Flameface даёт Strikethrough всем Pirates, включая себя. Блок героя остаётся значимым.','Anti-grave, splash и removal Flameface перед боем гасят одновременный урон.','aggro',8,2)
engine('graves','Gravestone replay','Mixed-Up_Gravedigger|Pogo_Zombie|Headstone_Carver','Играть скрытые угрозы с выгодными раскрытиями, затем повторять их через MUG.','MUG стоит 5 и заново прячет поле в надгробия. Перед повторным Pogo нужен доступный целевой боец; скрытые карты могут быть уничтожены анти-grave до выгодного раскрытия.','Blockbuster, Cool Bean и Grave Buster наказывают слишком много скрытых тел сразу.','control',7,3)
engine('science','Science attack','Gadget_Scientist|Zombot_Drone_Engineer|Cosmic_Scientist','Сохранить несколько Science-тел и обменять один розыгрыш Gadget на серию дополнительных атак.','Gadget Scientist запускает атаки каждого Science Zombie, включая себя. Нужны живые Science-основания и полезные цели; не-Science не атакует от этого триггера.','Удаление Science до Gadget и блокирование ранних ударов сокращают число полезных атак.','combo',7,2)
engine('mustache','Mustache economy','Mustache_Waxer|Duckstache','Использовать Mustache-карты одновременно как полезные действия и источник ресурса/живучести Waxer.','Текущий Waxer получает +2 Health и даёт +1 Brain на Mustache. Проверяйте тип трюка/существа, ресурс после каждой оплаты и порядок: Waxer должен уже стоять до следующего Mustache.','Удаление Waxer перед продолжением и налог на трюки превращают цепочку в обычную дорогую руку.','combo',8,3)
engine('blob','Brain production burst','Zom-Blob','Собрать ресурс текущего хода и превратить подходящее основание в крупный Blob для внезапной атаки.','Blob требует Zombie Evolution и считает все Brain, ПОЛУЧЕННЫЕ в этом ходу, а не остаток после оплаты. Он не копирует traits основания; бонусная атака/обход блока требуют отдельной карты.','Hard removal и bounce игнорируют высокую атаку; раннее давление вынуждает потратить основания и ресурсы.','combo',7,3)
engine('trickster','Trickster finish','Trickster','Пользоваться нужными трюками, пока они одновременно удешевляют финишер в руке.','Trickster должен быть в руке во время розыгрыша трюков для скидки. Teleport позволяет поставить его после Plants Play; цена Teleport тоже входит в расход хода.','Forget-Me-Nuts, Brainana и Untrickable сокращают доступность/полезность трюков.','control',8,2)
engine('valkyrie','Valkyrie reserve','Valkyrie','Конвертировать смерти недорогих зомби в атаку заранее полученной Valkyrie и завершить одним большим ударом.','Valkyrie растёт в руке на +2 Attack за уничтоженного Zombie. Перемещение, bounce и transform не считайте смертями. Для OTK нужен фактический проход к герою и проверка блока.','Bounce и hard removal огромной Valkyrie снимают весь накопленный payoff.','combo',6,3)
engine('leap','Leap progression','Evolutionary_Leap|Transformation_Station','Улучшать недорогие основания, получать ресурс и превращать промежуточные тела в новые угрозы.','Leap стоит 2 и превращает Zombie в случайного за стоимость +1, затем даёт карту. Station срабатывает на старте следующего хода, поэтому текущий розыгрыш не гарантирует немедленное превращение.','Уничтожение основания и перезапись среды обрывают вложение; случайный результат может оказаться хуже исходного.','value',6,8)
engine('mime','Mime bonus echo','Gargantuar_Mime|Mustache_Monument|Quarterly_Bonus','Повторять реальные бонусные атаки через Mime и создавать несколько ударов из ограниченного ресурса.','Mime реагирует на бонусную атаку НЕ-Mime растения или зомби; два Mime не запускают бесконечный цикл друг от друга. Quarterly устанавливает атаку на 4, а не прибавляет 4.','Wingnut запрещает бонусные атаки зомби, удаление Mime снимает вторую часть удара.','combo',6,3)
engine('pets','Pet tempo','Zookeeper|Cat_Lady','Использовать дешёвых Pets для быстрых усилений и выигрывать темпом ещё до дорогого payoff.','Проверяйте Pet-тип и живой Zookeeper до продолжения. Cat Lady получает кратковременный бонус; не считайте его сохранённым на следующий ход.','Splash снимает swarm, дешёвое удаление ключевого двигателя обнуляет темповую прибавку.','aggro',6,2)
engine('swimmer','Swimmer stat copy','Synchronized_Swimmer','Поставить крупную угрозу, затем воспроизвести её характеристики дешёвым вторым телом в другой линии.','Swimmer копирует текущие Attack/Health выбранного другого Zombie, НЕ его traits/текст. Без доступного живого образца остаётся маленькое тело; второй Zombie не получает Frenzy/Bullseye автоматически.','Removal образца до копирования и массовый ответ после него гасят план.','combo',7,2)
engine('gargs','Gargantuar pressure','Gargologist|Garg_Throwing_Garg|Gargantuar-Throwing_Imp|Supernova_Garg','Пережить начальную потерю темпа и создать несколько крупных угроз, сохраняя ответы на эффективное точечное удаление.','Gargologist даёт скидку Gargantuars только пока жив. Когда карта создаёт случайного Gargantuar, результат не является выбранным конкретным финишером.','Shamrocket и transform обмениваются выгодно с одним большим телом; swarm обгоняет тяжёлую руку.','midrange',6,5)
engine('frenzy','Frenzy tempo','Area_22|Maniacal_Laugh|Coffee_Zombie','Провести выгодное уничтожение блокера и превратить его в следующую атаку по герою.','Frenzy даёт дополнительную атаку только после уничтожения Plant, если Zombie выжил. Урон без убийства, смерть самого атакующего и bounce не запускают этот результат.','Высокое здоровье блокера, Freeze и removal атакующего останавливают повторный удар.','tempo',8,2)
engine('sports','Sports team','Team_Mascot|Zombie_Coach|Cosmic_Sports_Star','Собирать несколько Sports-тел и получать групповые усиления/защиту, удерживая доску.','Team Mascot требует живых Sports к своему триггеру. Coach защищает на ограниченный ход, а не делает всё поле постоянно бессмертным.','Splash/debuff до группового усиления и отсутствие добора делают длинную игру трудной.','midrange',6,2)
engine('viral','Going Viral swarm','Going_Viral|Flag_Zombie','Создавать широкое поле, затем превращать один трюк в усиление и Frenzy нескольких атакующих.','Viral усиливает текущих Zombies и подмешивает новые Viral; подмешивание не гарантирует немедленную следующую копию. Нужны живые тела и запас на цену трюка.','Mass removal перед Viral и Brainana в ключевой ход лишают группового payoff.','aggro',8,2)
engine('king','Knight conversion','Zombie_King','Оставлять недорогие основания для повторного превращения в устойчивые Knights в конце хода.','King превращает ДРУГОГО случайного Zombie, не себя. Цель не выбирается; полезный engine тоже может исчезнуть. Knight получает свои 5/5 Armored 2, исходный текст теряется.','Removal King до конца хода и уничтожение крупных Knights разрывают ценность.','value',6,5)
engine('pharaoh','Pharaoh survival','Undying_Pharaoh|Wannabe_Hero','Использовать позднюю живучесть как окно для атаки, сохраняя присутствие на поле и источник финиша.','Pharaoh предотвращает проигрыш при условии своего присутствия, но не защищён автоматически от transform/bounce. Большое здоровье Wannabe требует проверить актуальное здоровье героя при розыгрыше.','Transform и bounce убирают защиту, а заморозка/блокеры удерживают вашу позднюю атаку.','control',5,2)
engine('handbuff','Stompadon hand growth','Stompadon|Intergalactic_Warlord','Превращать будущие карты в более качественные тела и выигрывать повторными темповыми розыгрышами.','Stompadon баффает Zombies в текущей руке через Dino-Roar; трюки и уже стоящие тела не усиливаются этим событием.','Раннее удаление двигателя и быстрая гонка не дают окупить подготовку.','value',6,3)
engine('dance','Dancing burn','Aerobics_Instructor|Flamenco_Zombie|Disco-Tron_3000','Использовать Dancing-тела для давления и завершать прямым уроном Flamenco при достаточно широкой доске.','Flamenco считает Dancing Zombies на поле в момент способности; уничтоженные танцоры не входят в расчёт. Прямой урон и бой считаются отдельно.','Массовая зачистка до Flamenco и лечение с удалением двигателя разворачивают гонку.','aggro',7,2)
engine('binary','Binary burst','Binary_Stars','Сохранить удвоитель до следующего полезного источника урона и получить летал несколькими меньшими событиями.','Удвоение полезно только пока действует текущая способность Binary. Не стройте гарантированный летал на сообщённых BMR-багами множителях; они не стабильное правило.','Removal Binary до события урона и Armored на маленьких ударах снижают выигрыш.','combo',6,3)
engine('overshoot','Overshoot clock','Disco_Dance_Floor|Moon_Base_Z','Наносить урон по герою до обычного боя и вынуждать противника отвечать на источники прямого clock.','Overshoot не является обычной атакой в блокера; проверяйте действующего носителя, фазу и блок героя. Несколько источников не должны автоматически считаться Bullseye.','Environment replacement и лечение с контрдавлением нейтрализуют медленный источник урона.','aggro',7,2)
engine('draw_burn','Draw punishment','Quickdraw_Con_Man|Wormhole_Gatekeeper|Regifting_Zombie','Наказывать обычный добор, поддерживая темп и превращая дополнительные Draw в clock.','Quickdraw срабатывает на Draw, а не автоматически на любой Conjure/Shuffle. Симметричный добор усиливает и соперника: дайте его только когда выгода ваших двигателей больше.','Удаление Con Man перед Draw и лечение в темп обрывают наказание.','aggro',8,2)
engine('conjure_z','Zombie discovery','Dr._Spacetime|Buried_Treasure|Unexpected_Gifts|Thinking_Cap','Делать генерацию второй линией ресурса за полезным ранним давлением и адаптироваться к выпавшим картам.','Conjure не ищет конкретный ответ. Dr. Spacetime требует фактического урона герою для своей генерации; заблокированный удар не равен успешному триггеру.','Тёмповая агрессия и налоги на случайные трюки не дают окупить генерацию.','value',6,8)
engine('freeze_z','Zombie freeze','Cryo-Yeti|Unthawed_Viking|Frosty_Mustache','Замораживать важные блокеры и атаковать в окно, не тратя заморозку на несущественные линии.','Freeze останавливает бой на соответствующий ход, а не удаляет растение навсегда. Dino-Roar Cryo-Yeti требует получения карты; неизвестный будущий добор не гарантируется.','Несколько Team-Up-блокеров и removal ледяной угрозы переживают одиночное окно.','tempo',6,3)
engine('sun_denial','Sun denial','Ra_Zombie|Turquoise_Skull_Zombie','Создавать давление и сокращать ресурс следующего ответа Plants в нужную фазу.','Ra отнимает Sun при When played: в Zombie Tricks Plants уже потратили текущий ресурс, поэтому получение Ra из BMR не обязано приносить практическую выгоду.','Дешёвые Plants и уже стоящее поле обходят смысл позднего налога.','tempo',6,2)
engine('parasol','Protected zombie engine','Parasol_Zombie','Защитить важное поле от Plant Tricks и атаковать, заставляя противника использовать способности существ.','Проверьте охват Untrickable Parasol по линиям. Защита от трюков не отменяет Snapdragon, Cob Evolution и другие способности Plants.','Способности растений, debuff существами и давление из незакрытых линий обходят защиту.','midrange',7,2)
engine('death_z','Death value','Barrel_Of_Deadbeards|Gas_Giant|Final_Mission','Получать компенсацию за потерю тела и использовать sacrifice только если итог поля и ресурса выгоден.','Final Mission стоит 2, требует пожертвовать Zombie и наносит 4 урона PLANT, а не герою. Barrel при смерти повреждает и ваше поле: не уничтожайте весь собственный swarm ради одной цели.','Transform и bounce не запускают death-эффекты, а живые союзные 1-health тела гибнут от собственного Barrel.','tempo',7,3)
engine('tempo','Independent tempo','Tricarrotops|Veloci-Radish_Packmate|Space_Cowboy|Cyborg_Zombie|Bounty_Hunter','Играть самодостаточные угрозы по кривой и менять темп на урон, не ожидая редкой многокарточной комбинации.','Каждый бой оценивается по конкретным линиям; заранее назначьте карту для удаления и карту для атаки. Дополнительные ресурсы не считаются гарантированными, пока не выполнено условие эффекта.','Более выгодные размены и лечение в темп заставляют истратить руку до летала.','tempo',8,2)
engine('ramp_z','Brain acceleration','Cryo-Brain|Gentleman_Zombie|Medulla_Nebula','Пережить инвестицию в Brain и использовать большой следующий ход для нескольких действий, а не одного легко удаляемого тела.','Cryo-Brain даёт постоянный +1 Brain, Gentleman — +2 на старте Tricks. Medulla возвращает +2 за розыгрыш Zombie в своей линии в текущем ходу, а не постоянный ramp.','Агрессия и перезапись среды сокращают время, Brainana запрещает использовать накопленный Tricks-ресурс.','ramp',6,2)

