# Keep already published analyses; broad expansion adds distinct source lists,
# without cloning a list for the two heroes sharing the same classes.
def fingerprint(cards):return tuple(sorted((x['card'],x['count']) for x in cards))
def distance(a,b):
 a={x['card']:x['count'] for x in a};b={x['card']:x['count'] for x in b}
 return sum(abs(a.get(k,0)-b.get(k,0)) for k in a.keys()|b.keys())/2

def families(cards):
 m={x['card']:x['count'] for x in cards};out=[]
 for k,e in E.items():
  hit=[c for c in e['core'] if c in m]
  if k=='force_patch' and not all(c in m for c in ['Soul_Patch','Force_Field']):continue
  if k=='cycle' and not all(c in m for c in ['Astro_Shroom','Planet_of_the_Grapes']):continue
  if hit:
   # Generic shared pieces should not hide a real, narrower payoff.
   s=sum(m[c] for c in hit)/len(e['core'])**.4
   if k in ['bmr','force_patch','trickster','valkyrie','blob','pecan','rings','moss','pineclone','king','mirror','cycle']:s+=3
   if k in ['tempo','anti_trick','frenzy','death_z','draw_burn','ramp_p','ramp_z']:s-=1.5
   out.append((s,k))
 return [k for _,k in sorted(out,reverse=True)] or ['tempo']

used={fingerprint(d['cards']) for d in D}
for hid,(name,key,rows) in CUSTOM.items():
 slug=re.sub('[^a-z0-9]+','_',name.lower()).strip('_');did=hid+'/'+slug
 if did not in A:
  d=dict(id=did,hero=hid,name=name,slug=slug,category='theme-theorycraft',source_id=None,credit='HeroDecks',source_date='2026-10-14',cards=[dict(card=c,count=n) for c,n in rows],changes=[],family=key,theme=True)
  assert sum(n for _,n in rows)==40
  D.append(d);used.add(fingerprint(d['cards']))
# Fair round robin ensures shared-class heroes both have access to varied pools.
for roundnum in range(15):
 for hid,h in H.items():
  mine=[d for d in D if d['hero']==hid]
  if len(mine)>=15:continue
  famcounts=collections.Counter(d.get('family',families(d['cards'])[0]) for d in mine)
  candidates=[]
  for src in COR:
   if hid not in src['eligible_heroes'] or not src['structurally_valid'] or fingerprint(src['cards']) in used:continue
   if any(not C[x['card']]['deckable'] for x in src['cards']):continue
   fs=families(src['cards']);f=fs[0];mind=min(distance(src['cards'],d['cards']) for d in mine)
   if mind<9:continue
   early=sum(x['count'] for x in src['cards'] if C[x['card']]['cost']<=2)
   # Historical fun lists are welcome, but skeletons lacking an early game are not.
   if early<8:continue
   yearmatch=re.search(r'(20\d{2})',str(src.get('date','')));yr=int(yearmatch[1]) if yearmatch else 2017
   score=(12 if not famcounts[f] else -7*famcounts[f])+min(mind,27)*.7+max(0,yr-2022)*3.5+min(early,18)*.12
   score+=sum(1 for z in fs[:3] if not famcounts[z])*.8
   candidates.append((score,src['id'],src,f,fs,mind))
  if not candidates:raise ValueError('not enough diverse lists '+hid)
  _,_,src,f,fs,mind=max(candidates,key=lambda z:(z[0],z[1]))
  slug=f+'_'+(fs[1] if len(fs)>1 else 'solo')+'_'+src['id'].replace('deck_','').replace('-','n')
  secondary=next((E[k]['title'] for k in fs[1:] if k not in ['tempo','anti_trick']),C[src['cards'][0]['card']]['name']);name=E[f]['title']+' / '+secondary+' ['+src['id'].replace('deck_','')+']'
  d=dict(id=hid+'/'+slug,hero=hid,name=name,slug=slug,category='source-portfolio',source_id=src['id'],credit=src.get('credit') or 'не указан в корпусе',source_date=src.get('date') or 'не указана',cards=src['cards'],changes=[],family=f,source_name=src['name'],secondary_families=fs[1:3],selection_distance=mind)
  D.append(d);used.add(fingerprint(d['cards']))
assert len(D)==330, len(D)
