# Feature extraction is explicitly heuristic and auditable, not a battle simulator.
def features(d):
 cards=[(C[x['card']],x['count']) for x in d['cards']];out=collections.Counter()
 out['avg']=sum(c['cost']*n for c,n in cards)/40
 for c,n in cards:
  t=c['effect'].lower();out['early']+=n*(c['cost']<=2);out['late']+=n*(c['cost']>=5)
  out['tricks']+=n*('Trick' in c['type']);out['env']+=n*('Environment' in c['type'])
  out['bodies']+=n*(c['strength'] is not None)
  out['random']+=n*any(w in t for w in ['random','conjure'])
  out['draw']+=n*('draw' in t);out['conjure']+=n*('conjure' in t)
  out['removal']+=n*any(w in t for w in ['destroy','freeze','bounce','damage'])
  out['protection']+=n*any(w in t for w in ['untrickable','armored',"can't be hurt",'heal'])
  out['attack_access']+=n*any(w in t for w in ['strikethrough','bullseye','bonus attack','frenzy'])
  out['expensive']+=n*('legendary' in c['rarity'].lower());out['copies4']+=n*(n==4)
 return dict(out)

# Card roles for additions are strictly based on the stored wiki text. No invented
# tribal tags, damage targets, abilities inherited through copying or death events.
def role(c):
 t=c['effect'].lower()
 if c['id']=='Bad_Moon_Rising':return 'Финишер, обменивающий живое поле на случайные 5+-стоимостные угрозы; до сохранения нескольких тел не является рабочей зачисткой или гарантированным леталом.'
 if c['id']=='Force_Field':return 'Защита растений в одной ground-линии от повреждений. Сама не создаёт тело, не защищает от уничтожения/возврата и может быть заменена Zombie Environment.'
 if c['id']=='Soul_Patch':return 'Крупное защитное тело 5/10 Armored 1, принимающее урон героя; в Force Field этот урон предотвращается. Без поля запас здоровья конечен.'
 bits=[]
 if c['strength'] is not None:bits.append(f"Тело за {c['cost']} с исходными {c['strength']}/{c['health']} для занятия линии и боя")
 if 'environment' in c['type'].lower():bits.append('среда занимает только ground и требует сравнить её эффект с риском замены после Plants Play')
 if 'trick' in c['type'].lower():bits.append('трюк требует ресурса в фазе своей стороны и не оставляет постоянного бойца сам по себе')
 for word,desc in [('evolution','Evolution требует основания указанного в правиле типа; его цена и потеря входят в цену комбинации'),('fusion','Fusion требует последующего размещения карты на этом основании'),('conjure','Conjure расширяет выбор случайной картой, но не гарантирует нужное имя'),('draw','Draw пополняет руку из текущей колоды'),('freeze','Freeze создаёт временное окно без боя замороженной цели'),('bounce','Bounce возвращает цель в руку и покупает темп, не является уничтожением'),('destroy','уничтожение выполняется при указанном условии, без автоматической подмены на повреждение'),('gravestone','Gravestone скрывает тело до раскрытия и уязвим к отдельным ответам на надгробия'),('strikethrough','Strikethrough даёт давление через бойца, сохраняя проверку блока героя'),('bullseye','Bullseye уменьшает защитную выгоду зарядки блока от такого урона'),('frenzy','Frenzy требует уничтожить растение и выжить для следующей атаки'),('untrickable','Untrickable запрещает вражеские трюки по защищённой цели, но не способности существ'),('dino-roar','Dino-Roar требует реального получения карты в указанный момент')]:
  if word in t:bits.append(desc)
 return '; '.join(bits)+'. Точные цели, числовые пороги и timing берутся из правила выше, без расширения его смысла.'

def function_class(c):
 t=c['effect'].lower()
 if 'environment' in c['type'].lower():return 'environment'
 if any(w in t for w in ['destroy','bounce','freeze','damage']) and 'trick' in c['type'].lower():return 'answer'
 if 'trick' in c['type'].lower():return 'trick'
 if any(w in t for w in ['conjure','draw']):return 'resource_body'
 if c['cost']>=5:return 'late_body'
 return 'early_body'

def alternative(c,h,deckids):
 peers=[v for v in C.values() if v['deckable'] and v['id']!=c['id'] and v['faction']==h['faction'] and v['class'] in h['classes'] and function_class(v)==function_class(c)]
 if not peers:return 'Допустимой прямой замены с тем же правилом нет: менять следует весь связанный пакет, сохраняя ранние ответы и 40 карт.'
 # Same class is preferred; different card text is not declared equivalent.
 peers.sort(key=lambda v:(v['id'] in deckids,v['class']!=c['class'],abs(v['cost']-c['cost']),v['name']))
 alt=peers[0]
 return f"Сравните с {alt['name']} ({alt['class']}, цена {alt['cost']}, {str(alt['strength'])+'/'+str(alt['health']) if alt['strength'] is not None else 'без обычного тела'}): это легальная альтернатива героя с другой ценой/правилом, а не взаимозаменяемая копия. В этой версии выбран точный эффект {c['name']}; замена меняет функцию пакета и требует нового расчёта кривой. Правило альтернативы: {alt['effect']}"

